class Counter:
    def __init__(self):
        self.count = 0

    def increment(self):
        self.count += 1

def sum_list(numbers):
    total = 0
    for n in numbers:
        total += n
    return total

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def bubble_sort(items):
    items = items.copy()
    n = len(items)
    for i in range(n):
        for j in range(n - i - 1):
            if items[j] > items[j + 1]:
                items[j], items[j + 1] = items[j + 1], items[j]
    return items

def factorial(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result
